#!/usr/bin/env node
// Compiles the JSON Schema into lib/validator.generated.js, a standalone
// validator the player can run in the browser without shipping Ajv.
//
// The generated file isn't committed: `npm run check`, `npm run demo` and
// `npm run site` build it first.

import { readFileSync, writeFileSync } from 'node:fs';
import Ajv2020 from 'ajv/dist/2020.js';
import standaloneCode from 'ajv/dist/standalone/index.js';

const root = new URL('../', import.meta.url);
const schema = JSON.parse(readFileSync(new URL('schema/pwf-0.1.schema.json', root), 'utf8'));

// Formats (uri, date-time) aren't checked in the browser: they would pull in
// ajv-formats, and the conformance check covers them.
const ajv = new Ajv2020({
  allErrors: true,
  strict: true,
  strictRequired: false,
  validateFormats: false,
  code: { source: true, esm: true },
});
let code = standaloneCode(ajv, ajv.compile(schema));

// Ajv's generated code requires two small runtime helpers. Inline them so the
// file is a plain ES module with no imports.
const runtime = {
  'ajv/dist/runtime/ucs2length': 'function ucs2length(s) { return [...s].length; }',
  'ajv/dist/runtime/equal': `function equal(a, b) {
  if (a === b) return true;
  if (!a || !b || typeof a !== 'object' || typeof b !== 'object') return a !== a && b !== b;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length && keys.every((k) => Object.hasOwn(b, k) && equal(a[k], b[k]));
}`,
};
code = code.replace(/const (\w+) = require\("([^"]+)"\)\.default;/g, (line, name, module) => {
  if (!runtime[module]) throw new Error(`build.mjs doesn't know how to inline ${module}`);
  return `const ${name} = ${runtime[module].replace(/^function (\w+)/, 'function')};`;
});
if (code.includes('require(')) throw new Error('The generated validator still has a require()');

const header = '// Generated by tools/build.mjs from schema/pwf-0.1.schema.json. Do not edit.\n';
writeFileSync(new URL('lib/validator.generated.js', root), header + code);
console.log('Built lib/validator.generated.js');
